                            int nr = r + dr, nc = c + dc;
                            if (nr >= 0 && nr < rows && nc >= 0 && nc < columns &&
                                land[nr][nc] == 0 && !seen[nr, nc])
                            {
                                seen[nr, nc] = true;
                                work.Push((nr, nc));
                            }
                        }
                    }
                }
                sizes.Add(size);
            }
        }
        sizes.Sort();
        return sizes.ToArray();
    }
}

